{"command":"create","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { logger } from '../../../packages/observability/src/logger.js';
import type { ErasureRequestRow } from './repository.js';

export async function executeErasure(merchantId: string, customerId: string, requestId: string): Promise<void> {
  // 1. Fetch customer details if row exists
  const customerResult = await pool.query<{ email: string; phone: string | null; name: string }>(
    `SELECT email, phone, name FROM customers.customers WHERE merchant_id = $1 AND id = $2`,
    [merchantId, customerId],
  );
  let email = customerResult.rows[0]?.email;
  if (!email) {
    const emailDeliv = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2 LIMIT 1`,
      [merchantId, customerId],
    );
    email = emailDeliv.rows[0]?.destination;
  }
  if (!email) {
    const notif = await pool.query<{ destination: string }>(
      `SELECT destination FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2 LIMIT 1`,
      [merchantId, customerId],
    );
    email = notif.rows[0]?.destination;
  }

  // 2. Redact receipts in MinIO & update manifests
  const receipts = await pool.query<{ object_key: string }>(
    `SELECT object_key FROM operations.document_manifests
     WHERE merchant_id = $1 AND document_type = 'receipt'
       AND (customer_id = $2 OR metadata->>'paymentId' IN (
         SELECT id::text FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       ))`,
    [merchantId, customerId],
  );
  for (const receipt of receipts.rows) {
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, receipt.object_key);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) chunks.push(Buffer.from(chunk));
      const parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
      parsed.customer = { redacted: true };
      const updatedBody = JSON.stringify(parsed);
      await objectStore.putObject(DOCUMENT_BUCKET, receipt.object_key, updatedBody, Buffer.byteLength(updatedBody), {
        'Content-Type': 'application/json',
      });
      const checksum = createHash('sha256').update(updatedBody).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests SET checksum = $1, customer_id = NULL WHERE merchant_id = $2 AND object_key = $3`,
        [checksum, merchantId, receipt.object_key],
      );
    } catch (err: unknown) {
      const error = err as { code?: string };
      if (error?.code !== 'NoSuchKey' && error?.code !== 'NotFound') {
        logger.warn({ err, objectKey: receipt.object_key }, 'failed to update receipt in object store');
      }
    }
  }

  // 3. Redact invoices in MinIO & update manifests
  const invoices = await pool.query<{ object_key: string }>(
    `SELECT object_key FROM payments.invoices WHERE merchant_id = $1 AND customer_id = $2 AND object_key IS NOT NULL`,
    [merchantId, customerId],
  );
  for (const invoice of invoices.rows) {
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, invoice.object_key);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) chunks.push(Buffer.from(chunk));
      const parsed = JSON.parse(Buffer.concat(chunks).toString('utf8'));
      parsed.customer = { redacted: true };
      const updatedBody = JSON.stringify(parsed);
      await objectStore.putObject(DOCUMENT_BUCKET, invoice.object_key, updatedBody, Buffer.byteLength(updatedBody), {
        'Content-Type': 'application/json',
      });
      const checksum = createHash('sha256').update(updatedBody).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests SET checksum = $1, customer_id = NULL WHERE merchant_id = $2 AND object_key = $3`,
        [checksum, merchantId, invoice.object_key],
      );
    } catch (err: unknown) {
      const error = err as { code?: string };
      if (error?.code !== 'NoSuchKey' && error?.code !== 'NotFound') {
        logger.warn({ err, objectKey: invoice.object_key }, 'failed to update invoice in object store');
      }
    }
  }

  // 4. Clean up customer imports from MinIO & DB
  const imports = await pool.query<{ object_key: string; import_id: string | null }>(
    `SELECT object_key, metadata->>'importId' as import_id FROM operations.document_manifests
     WHERE merchant_id = $1 AND document_type = 'customer_import'
       AND (customer_id = $2 OR metadata->>'customerId' = $2::text)`,
    [merchantId, customerId],
  );
  for (const imp of imports.rows) {
    try {
      await objectStore.removeObject(DOCUMENT_BUCKET, imp.object_key);
    } catch {}
    await pool.query(`DELETE FROM operations.document_manifests WHERE merchant_id = $1 AND object_key = $2`, [merchantId, imp.object_key]);
    if (imp.import_id) {
      await pool.query(`DELETE FROM customers.customer_imports WHERE merchant_id = $1 AND id = $2`, [merchantId, imp.import_id]);
    }
  }

  // 5. Redis cache removal
  const redis = new Redis(config().REDIS_URL);
  try {
    const key = `merchant:${merchantId}:customer:${customerId}`;
    await redis.del(key);
    await redis.del(`${key}:activity`);
    let cursor = '0';
    do {
      const [nextCursor, keys] = await redis.scan(cursor, 'MATCH', `${key}*`, 'COUNT', 100);
      cursor = nextCursor;
      if (keys.length > 0) {
        await redis.del(...keys);
      }
    } while (cursor !== '0');
  } finally {
    await redis.quit();
  }

  // 6. OpenSearch index document deletion
  try {
    await searchClient.delete({
      index: CUSTOMER_INDEX,
      id: `${merchantId}:${customerId}`,
      refresh: true,
    });
  } catch (err: unknown) {
    const error = err as { statusCode?: number; meta?: { statusCode?: number } };
    if (error?.statusCode !== 404 && error?.meta?.statusCode !== 404) {
      // ignore
    }
  }

  // 7. Mailpit emails deletion
  if (email) {
    try {
      await deleteMailpitMessagesForRecipient(email);
    } catch {}
  }

  // 8. Postgres data cleanup & financial records redaction in transaction
  await transaction(async (client) => {
    // Child customer records
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);

    // Support tickets & messages
    await client.query(
      `DELETE FROM customers.support_messages WHERE merchant_id = $1 AND (author_id = $2 OR ticket_id IN (SELECT ticket_id FROM customers.support_participants WHERE customer_id = $2))`,
      [merchantId, customerId],
    );
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id = $1`, [customerId]);
    await client.query(
      `DELETE FROM customers.support_tickets WHERE merchant_id = $1 AND NOT EXISTS (SELECT 1 FROM customers.support_participants sp WHERE sp.ticket_id = customers.support_tickets.id)`,
      [merchantId],
    );

    // Main customer row
    await client.query(`DELETE FROM customers.customers WHERE merchant_id = $1 AND id = $2`, [merchantId, customerId]);

    // Financial records redaction
    await client.query(
      `UPDATE payments.payment_intents SET customer_snapshot = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.payment_attempts
       SET request_payload = jsonb_set(request_payload, '{customer}', '{"redacted": true}'::jsonb, false),
           response_payload = CASE WHEN response_payload IS NOT NULL AND response_payload ? 'customer' THEN jsonb_set(response_payload, '{customer}', '{"redacted": true}'::jsonb, false) ELSE response_payload END
       WHERE merchant_id = $1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2)`,
      [merchantId, customerId],
    );
    if (email) {
      await client.query(
        `UPDATE payments.refunds SET customer_email = NULL WHERE merchant_id = $1 AND (customer_email = $2 OR payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $3))`,
        [merchantId, email, customerId],
      );
    } else {
      await client.query(
        `UPDATE payments.refunds SET customer_email = NULL WHERE merchant_id = $1 AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2)`,
        [merchantId, customerId],
      );
    }
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // Operations schema
    await client.query(
      `DELETE FROM operations.analytics_events WHERE merchant_id = $1 AND (customer_id = $2 OR properties->>'customerId' = $2::text OR anonymous_id = 'anon_' || $2::text)`,
      [merchantId, customerId],
    );
    if (email) {
      await client.query(`DELETE FROM operations.analytics_events WHERE merchant_id = $1 AND email = $2`, [merchantId, email]);
    }
    await client.query(`DELETE FROM operations.notification_preferences WHERE merchant_id = $1 AND customer_id = $2`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.notifications WHERE merchant_id = $1 AND (customer_id = $2 OR payload->>'customerId' = $2::text)`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.email_deliveries WHERE merchant_id = $1 AND (customer_id = $2 OR (destination = $3 AND $3 IS NOT NULL))`, [merchantId, customerId, email ?? null]);
    await client.query(`DELETE FROM operations.jobs WHERE merchant_id = $1 AND (payload->>'customerId' = $2::text OR payload->'customerSnapshot'->>'id' = $2::text)`, [merchantId, customerId]);
    await client.query(`DELETE FROM operations.dead_letters WHERE payload->>'customerId' = $1::text OR payload->'customer'->>'id' = $1::text OR payload->'customerSnapshot'->>'id' = $1::text`, [customerId]);
    await client.query(`DELETE FROM operations.outbox_events WHERE merchant_id = $1 AND status <> 'published' AND (aggregate_id = $2 OR payload->>'customerId' = $2::text)`, [merchantId, customerId]);

    // Platform audit logs metadata redaction
    await client.query(`UPDATE platform.audit_logs SET metadata = '{"redacted": true}'::jsonb WHERE merchant_id = $1 AND target_type = 'customer' AND target_id = $2::text`, [merchantId, customerId]);

    // Provider sandbox
    await client.query(`DELETE FROM provider_sandbox.customers WHERE merchant_id = $1 AND (payflow_customer_id = $2 OR (email = $3 AND $3 IS NOT NULL))`, [merchantId, customerId, email ?? null]);

    // Outbox event
    await addOutboxEvent(client, {
      eventType: EVENT_TYPES.CUSTOMER_ERASED,
      aggregateType: 'customer',
      aggregateId: customerId,
      merchantId,
      correlationId: randomUUID(),
      payload: { customerId },
    });

    // Mark erasure request as completed
    await client.query(
      `UPDATE customers.erasure_requests
       SET status = 'completed', completed_at = now(), updated_at = now(),
           locked_by = NULL, locked_at = NULL, lease_expires_at = NULL, last_error = NULL
       WHERE id = $1`,
      [requestId],
    );
  });
}

export async function claimErasureRequest(workerId: string, leaseSeconds = 60): Promise<ErasureRequestRow | undefined> {
  const result = await pool.query<ErasureRequestRow>(
    `UPDATE customers.erasure_requests
     SET status = 'processing', attempts = attempts + 1, locked_by = $1, locked_at = now(),
         lease_expires_at = now() + ($2 || ' seconds')::interval, last_error = NULL, updated_at = now()
     WHERE id = (
       SELECT id FROM customers.erasure_requests
       WHERE status IN ('pending', 'failed') AND next_attempt_at <= now()
       ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1
     )
     RETURNING *`,
    [workerId, leaseSeconds],
  );
  return result.rows[0];
}

export async function recoverExpiredErasureLeases(): Promise<number> {
  const result = await pool.query(
    `UPDATE customers.erasure_requests
     SET status = 'pending', locked_by = NULL, locked_at = NULL, lease_expires_at = NULL,
         last_error = COALESCE(last_error, 'worker_lease_expired'), updated_at = now()
     WHERE status = 'processing' AND lease_expires_at < now()`,
  );
  return result.rowCount ?? 0;
}

export async function startErasureWorker(signal: AbortSignal): Promise<void> {
  const workerId = `erasure-worker-${randomUUID()}`;
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredErasureLeases().catch(() => {});
      lastLeaseRecovery = Date.now();
    }
    const job = await claimErasureRequest(workerId).catch((error) => {
      logger.error({ error }, 'failed to claim erasure request');
      return undefined;
    });
    if (!job) {
      await new Promise((resolve) => setTimeout(resolve, 200));
      continue;
    }
    try {
      await executeErasure(job.merchant_id, job.customer_id, job.id);
    } catch (error) {
      logger.error({ error, requestId: job.id }, 'erasure execution failed');
      await pool.query(
        `UPDATE customers.erasure_requests
         SET status = 'failed', last_error = 'cleanup_failed',
             locked_by = NULL, locked_at = NULL, lease_expires_at = NULL,
             updated_at = now(), next_attempt_at = now() + interval '5 seconds'
         WHERE id = $1`,
        [job.id],
      ).catch(() => {});
    }
  }
}
