{"file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import { randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { config } from '../packages/config/src/index.js';
import { pool, transaction } from '../packages/database/src/pool.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const apiKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const secondMerchantApiKey = 'pf_local_dev_bluebird_924bd90d2201';

async function api<T>(
  path: string,
  method = 'GET',
  body?: unknown,
  extraHeaders: Record<string, string> = {},
  key = apiKey,
): Promise<{ status: number; data: T }> {
  const headers: Record<string, string> = { authorization: `Bearer ${key}`, ...extraHeaders };
  const init: RequestInit = { method, headers };
  if (body !== undefined) {
    headers['content-type'] = 'application/json';
    init.body = JSON.stringify(body);
  }
  const response = await fetch(`${gateway}${path}`, init);
  let data: T;
  try {
    data = await response.json() as T;
  } catch {
    data = {} as T;
  }
  return { status: response.status, data };
}

test('customer erasure API validation and access control', async () => {
  // 1. Create a customer
  const suffix = randomUUID().slice(0, 8);
  const created = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `test-erase-${suffix}`,
    email: `test.erase.${suffix}@example.test`,
    name: `Test User ${suffix}`,
  });
  assert.equal(created.status, 201);
  const customerId = created.data.id;

  // 2. Reject short idempotency key (< 8 chars)
  const shortKeyRes = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': 'short',
  });
  assert.equal(shortKeyRes.status, 400);

  // 3. Reject non-existent customer
  const nonExistentCustomerId = randomUUID();
  const notFoundRes = await api(`/v1/customers/${nonExistentCustomerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': `key-notfound-${suffix}`,
  });
  assert.equal(notFoundRes.status, 404);

  // 4. Reject customer belonging to another merchant
  const otherMerchantCustomerRes = await api(
    `/v1/customers/${customerId}/erasure-requests`,
    'POST',
    undefined,
    { 'idempotency-key': `key-other-${suffix}` },
    secondMerchantApiKey,
  );
  assert.equal(otherMerchantCustomerRes.status, 404);

  // 5. Valid erasure request returns 202 with pending/processing/completed status
  const validKey = `key-valid-${suffix}`;
  const erasureRes = await api<{
    id: string;
    customerId: string;
    status: string;
    attempts: number;
    createdAt: string;
    updatedAt: string;
    completedAt: string | null;
    lastError: string | null;
  }>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': validKey,
  });
  assert.equal(erasureRes.status, 202);
  assert.equal(erasureRes.data.customerId, customerId);
  assert.ok(erasureRes.data.id);
  assert.ok(['pending', 'processing', 'completed'].includes(erasureRes.data.status));
  const requestId = erasureRes.data.id;

  // 6. Reusing idempotency key for the same customer returns the same request
  const replaySameKey = await api<{ id: string; customerId: string }>(
    `/v1/customers/${customerId}/erasure-requests`,
    'POST',
    undefined,
    { 'idempotency-key': validKey },
  );
  assert.equal(replaySameKey.status, 202);
  assert.equal(replaySameKey.data.id, requestId);
  assert.equal(replaySameKey.data.customerId, customerId);

  // 7. Reusing idempotency key for a different customer returns 409 Conflict
  const secondCustomer = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `test-second-${suffix}`,
    email: `test.second.${suffix}@example.test`,
    name: `Second User ${suffix}`,
  });
  assert.equal(secondCustomer.status, 201);
  const conflictRes = await api(
    `/v1/customers/${secondCustomer.data.id}/erasure-requests`,
    'POST',
    undefined,
    { 'idempotency-key': validKey },
  );
  assert.equal(conflictRes.status, 409);

  // 8. New idempotency key for customer that already has erasure request returns existing request
  const newKey = `key-another-${suffix}`;
  const existingCustomerRes = await api<{ id: string; customerId: string }>(
    `/v1/customers/${customerId}/erasure-requests`,
    'POST',
    undefined,
    { 'idempotency-key': newKey },
  );
  assert.equal(existingCustomerRes.status, 202);
  assert.equal(existingCustomerRes.data.id, requestId);
  assert.equal(existingCustomerRes.data.customerId, customerId);

  // 9. GET erasure request status
  const getStatus = await api<{ id: string; customerId: string; status: string }>(
    `/v1/erasure-requests/${requestId}`,
  );
  assert.equal(getStatus.status, 200);
  assert.equal(getStatus.data.id, requestId);
  assert.equal(getStatus.data.customerId, customerId);

  // 10. GET non-existent erasure request returns 404
  const notFoundGet = await api(`/v1/erasure-requests/${randomUUID()}`);
  assert.equal(notFoundGet.status, 404);

  // 11. GET erasure request by another merchant returns 404
  const otherMerchantGet = await api(
    `/v1/erasure-requests/${requestId}`,
    'GET',
    undefined,
    {},
    secondMerchantApiKey,
  );
  assert.equal(otherMerchantGet.status, 404);
});

test('customer data deletion removes personal data while retaining financial facts', async () => {
  const suffix = randomUUID().slice(0, 8);
  const email = `ada.privacy.${suffix}@example.test`;
  const name = `Ada Privacy ${suffix}`;
  const phone = `+1-415-555-${Math.floor(1000 + Math.random() * 9000)}`;

  // 1. Create full customer profile with address, contact, payment method, support ticket, import, invoice, and payment
  const customer = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `crm-privacy-${suffix}`,
    email,
    name,
    phone,
    metadata: { plan: 'enterprise', testRun: suffix },
  });
  assert.equal(customer.status, 201);
  const customerId = customer.data.id;

  const address = await api(`/v1/customers/${customerId}/addresses`, 'POST', {
    kind: 'billing',
    line1: '123 Privacy Lane',
    city: 'San Francisco',
    region: 'CA',
    postalCode: '94105',
    country: 'US',
  });
  assert.equal(address.status, 201);

  const contact = await api(`/v1/customers/${customerId}/contacts`, 'POST', {
    kind: 'email',
    value: email,
    isPrimary: true,
  });
  assert.equal(contact.status, 201);

  const method = await api<{ id: string }>(`/v1/customers/${customerId}/payment-methods`, 'POST', {
    providerToken: `tok_live_${randomUUID()}`,
    type: 'card',
    brand: 'visa',
    last4: '4242',
    billingName: name,
    billingAddress: { line1: '123 Privacy Lane', city: 'San Francisco', postalCode: '94105', country: 'US' },
  });
  assert.equal(method.status, 201);

  const ticket = await api(`/v1/customers/${customerId}/support-tickets`, 'POST', {
    subject: 'Privacy support inquiry',
    body: `Please delete my data for ${email}`,
  });
  assert.equal(ticket.status, 201);

  const importRes = await api('/v1/customer-imports', 'POST', {
    source: 'test-import',
    record: { customerId, email, name, phone },
  });
  assert.equal(importRes.status, 201);

  const invoice = await api<{ id: string; objectKey: string }>('/v1/invoices', 'POST', {
    customerId,
    currency: 'USD',
    tax: 50,
    lines: [{ description: 'Privacy Subscription', quantity: 1, unitAmount: 2000 }],
  });
  assert.equal(invoice.status, 201);

  const payment = await api<{ id: string }>('/v1/payments', 'POST', {
    customerId,
    paymentMethodId: method.data.id,
    amount: 2000,
    currency: 'USD',
    description: `Order for ${name}`,
  }, { 'idempotency-key': `pay-key-${suffix}` });
  assert.equal(payment.status, 202);
  const paymentId = payment.data.id;

  // Allow async projections / receipts / webhooks to settle
  await new Promise((resolve) => setTimeout(resolve, 3_000));

  // Verify customer is in OpenSearch and Redis before deletion
  const searchBefore = await searchClient.search({
    index: CUSTOMER_INDEX,
    body: { query: { term: { customerId } } },
  });
  assert.equal(searchBefore.body.hits.total.value, 1, 'Customer should be indexed in OpenSearch before erasure');

  const redis = new Redis(config().REDIS_URL);
  const northstarMerchantId = '10000000-0000-4000-8000-000000000001';
  const redisCacheKey = `merchant:${northstarMerchantId}:customer:${customerId}`;
  const redisDocBefore = await redis.get(redisCacheKey);
  assert.ok(redisDocBefore, 'Customer projection should exist in Redis before erasure');

  // 2. Request erasure
  const erasure = await api<{ id: string; status: string }>(
    `/v1/customers/${customerId}/erasure-requests`,
    'POST',
    undefined,
    { 'idempotency-key': `erasure-full-${suffix}` },
  );
  assert.equal(erasure.status, 202);
  const requestId = erasure.data.id;

  // 3. Poll until erasure request status becomes 'completed'
  let completed = false;
  for (let i = 0; i < 30; i += 1) {
    const statusRes = await api<{ status: string; completedAt: string | null; lastError: string | null }>(
      `/v1/erasure-requests/${requestId}`,
    );
    if (statusRes.data.status === 'completed') {
      completed = true;
      assert.ok(statusRes.data.completedAt);
      assert.equal(statusRes.data.lastError, null);
      break;
    }
    if (statusRes.data.status === 'failed') {
      throw new Error(`Erasure request failed: ${statusRes.data.lastError}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  assert.ok(completed, 'Erasure request should complete within timeout');

  // 4. Verify customer profile is deleted (GET /v1/customers/:id -> 404)
  const getCustomer = await api(`/v1/customers/${customerId}`);
  assert.equal(getCustomer.status, 404, 'Customer record should return 404 after erasure');

  // 5. Verify child records are deleted
  const dbAddresses = await pool.query(`SELECT 1 FROM customers.addresses WHERE customer_id=$1`, [customerId]);
  assert.equal(dbAddresses.rowCount, 0, 'Addresses should be deleted');

  const dbContacts = await pool.query(`SELECT 1 FROM customers.contacts WHERE customer_id=$1`, [customerId]);
  assert.equal(dbContacts.rowCount, 0, 'Contacts should be deleted');

  const dbPaymentMethods = await pool.query(`SELECT 1 FROM customers.payment_method_refs WHERE customer_id=$1`, [customerId]);
  assert.equal(dbPaymentMethods.rowCount, 0, 'Payment methods should be deleted');

  const dbProviderMappings = await pool.query(`SELECT 1 FROM customers.provider_customer_mappings WHERE customer_id=$1`, [customerId]);
  assert.equal(dbProviderMappings.rowCount, 0, 'Provider customer mappings should be deleted');

  // 6. Verify financial records are retained with redacted PII
  const dbPayments = await pool.query<{ customer_snapshot: Record<string, unknown>; amount: string; status: string }>(
    `SELECT customer_snapshot, amount, status FROM payments.payment_intents WHERE id=$1`,
    [paymentId],
  );
  assert.equal(dbPayments.rowCount, 1, 'Payment intent must be retained for financial records');
  assert.deepEqual(dbPayments.rows[0]?.customer_snapshot, { redacted: true }, 'Payment intent customer_snapshot must be redacted');

  const dbInvoices = await pool.query<{ billing_snapshot: Record<string, unknown>; total: string }>(
    `SELECT billing_snapshot, total FROM payments.invoices WHERE id=$1`,
    [invoice.data.id],
  );
  assert.equal(dbInvoices.rowCount, 1, 'Invoice must be retained for financial records');
  assert.deepEqual(dbInvoices.rows[0]?.billing_snapshot, { redacted: true }, 'Invoice billing_snapshot must be redacted');

  // 7. Verify MinIO objects are redacted and document manifests agree
  const receiptManifest = await pool.query<{ object_key: string; checksum: string }>(
    `SELECT object_key, checksum FROM operations.document_manifests WHERE metadata->>'paymentId'=$1`,
    [paymentId],
  );
  if (receiptManifest.rows[0]) {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, receiptManifest.rows[0].object_key);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(Buffer.from(chunk));
    const receiptDoc = JSON.parse(Buffer.concat(chunks).toString('utf8'));
    assert.deepEqual(receiptDoc.customer, { redacted: true }, 'MinIO receipt customer must be redacted');
  }

  // 8. Verify Redis projections are deleted
  const redisDocAfter = await redis.get(redisCacheKey);
  assert.equal(redisDocAfter, null, 'Redis customer projection must be deleted');
  const redisActivityAfter = await redis.hgetall(`${redisCacheKey}:activity`);
  assert.deepEqual(redisActivityAfter, {}, 'Redis customer activity projection must be deleted');

  // 9. Verify OpenSearch document is deleted
  const searchAfter = await searchClient.search({
    index: CUSTOMER_INDEX,
    body: { query: { term: { customerId } } },
  });
  assert.equal(searchAfter.body.hits.total.value, 0, 'OpenSearch customer document must be deleted');

  // 10. Verify operations and provider sandbox PII is erased
  const dbNotifications = await pool.query(`SELECT 1 FROM operations.notification_preferences WHERE customer_id=$1`, [customerId]);
  assert.equal(dbNotifications.rowCount, 0, 'Notification preferences must be deleted');

  const dbSandboxCustomers = await pool.query(`SELECT 1 FROM provider_sandbox.customers WHERE payflow_customer_id=$1`, [customerId]);
  assert.equal(dbSandboxCustomers.rowCount, 0, 'Sandbox provider customers must be deleted');

  await redis.quit();
});
